<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR {{ $asset->asset_code }}</title><style>@page{size:A4 portrait;margin:15mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#111}.tools{display:flex;justify-content:flex-end;gap:8px;margin-bottom:20px}.tools a,.tools button{padding:9px 14px;border:1px solid #ccc;border-radius:6px;background:#fff;text-decoration:none;color:#222}.tools button{background:#047857;color:#fff;border-color:#047857}.sheet{width:105mm;margin:25mm auto 0;padding:12mm;border:1px solid #777;text-align:center}.school{display:flex;align-items:center;justify-content:center;gap:10px;padding-bottom:9mm;border-bottom:1px solid #aaa}.school img{width:16mm;height:16mm;object-fit:contain}.school strong{font-size:13pt}.qr{width:64mm;height:64mm;margin:10mm auto 5mm}.sheet h1{margin:0 0 3mm;font-size:17pt}.code{font-size:11pt;font-weight:bold}.scan{margin:7mm 0 0;padding-top:5mm;border-top:1px solid #bbb;font-size:9pt}.label-link{margin-top:5mm;font-size:7pt;color:#555}@media print{.tools{display:none}.sheet{margin:12mm auto 0}}</style></head><body><div class="tools"><a href="{{ route('asset-qr-codes.index') }}">Kembali</a><button onclick="window.print()">Print QR</button></div><main class="sheet"><div class="school">@if($schoolSetting->logo_url)<img src="{{ $schoolSetting->logo_url }}" alt="Logo">@endif<strong>{{ $schoolSetting->display_name }}</strong></div><img class="qr" src="{{ $qrDataUri }}" alt="QR {{ $asset->asset_code }}"><h1>{{ $asset->name }}</h1><div class="code">{{ $asset->asset_code }}</div><p class="scan">Scan untuk melihat informasi aset</p><p class="label-link">Gunakan menu Cetak Label untuk label inventaris lengkap.</p></main><script>window.addEventListener('load',()=>window.print())</script></body></html>
